def test_sub_positive_minus_positive():
    """If the function 'sub' is called with two positive integers (e.g., 10 and 5), then it should return the correct difference (5). This tests the core functionality of subtracting two standard positive integers as described in the documentation."""
    assert sub(10, 5) == 5

def test_sub_positive_minus_negative():
    """If the function 'sub' is called with a positive integer 'a' (e.g., 10) and a negative integer 'b' (e.g., -5), then it should return the sum of their magnitudes (15). This tests the behavior of subtracting a negative number, which is mathematically equivalent to addition, ensuring the implementation handles signed integers correctly."""
    assert sub(10, -5) == 15

def test_sub_negative_minus_positive():
    """If the function 'sub' is called with a negative integer 'a' (e.g., -10) and a positive integer 'b' (e.g., 5), then it should return the correct negative difference (-15). This tests the behavior when the minuend is negative and the subtrahend is positive."""
    assert sub(-10, 5) == -15

def test_sub_negative_minus_negative():
    """If the function 'sub' is called with two negative integers (e.g., -10 and -5), then it should return the correct difference (-5). This tests the behavior of subtracting a negative number from another negative number."""
    assert sub(-10, -5) == -5

def test_sub_equal_integers():
    """If the function 'sub' is called with two identical integers (e.g., 7 and 7), then it should return 0. This tests the edge case where the minuend and subtrahend are equal, ensuring the result is zero."""
    assert sub(7, 7) == 0

def test_sub_zero_minus_positive():
    """If the function 'sub' is called with zero as 'a' (0) and a positive integer as 'b' (e.g., 5), then it should return the negative of 'b' (-5). This tests the behavior of subtracting a positive integer from zero."""
    assert sub(0, 5) == -5

def test_sub_positive_minus_zero():
    """If the function 'sub' is called with a positive integer as 'a' (e.g., 5) and zero as 'b' (0), then it should return the value of 'a' (5). This tests the behavior of subtracting zero from a positive integer."""
    assert sub(5, 0) == 5

def test_sub_zero_minus_zero():
    """If the function 'sub' is called with zero for both 'a' and 'b' (0 and 0), then it should return 0. This tests the edge case where both operands are zero."""
    assert sub(0, 0) == 0

def test_sub_zero_minus_negative():
    """If the function 'sub' is called with zero as 'a' (0) and a negative integer as 'b' (e.g., -5), then it should return the positive equivalent of 'b' (5). This tests the behavior of subtracting a negative integer from zero."""
    assert sub(0, -5) == 5

def test_sub_negative_minus_zero():
    """If the function 'sub' is called with a negative integer as 'a' (e.g., -5) and zero as 'b' (0), then it should return the value of 'a' (-5). This tests the behavior of subtracting zero from a negative integer."""
    assert sub(-5, 0) == -5

def test_sub_large_integers():
    """If the function 'sub' is called with very large integers (e.g., 10**100 and 10**99), then it should return the correct mathematical difference without overflow errors. This tests that the implementation handles Python's arbitrary-precision integers correctly, as implied by the `int` type hint."""
    assert sub(10**100, 10**99) == 9 * 10**99

def test_sub_bool_as_int():
    """If the function 'sub' is called with boolean values (e.g., True and False), which are subclasses of `int` in Python, then it should return the correct integer result (1). This tests that the function behaves consistently with Python's type system where `bool` is treated as `int`."""
    assert sub(True, False) == 1

